def main():
    old=json.loads((ROOT/'.g5/uplift/consolidated/iter2/member-dispositions.json').read_text());inventory={x['member']:dict(x) for x in old}
    assert len(inventory)==1216
    canonical={}
    for path in (ROOT/'.g5/ontology').rglob('*.g5.md'):
        raw=path.read_text();blocks=list(re.finditer(r'^\[([IDQ]) · ([^\]]+)\]\n',raw,re.M))
        for i,m in enumerate(blocks):
            id=m[2];assert id not in canonical,id
            end=blocks[i+1].start() if i+1<len(blocks) else raw.find('## Metadata',m.end())
            body=raw[m.end():end if end!=-1 else len(raw)].strip()
            meta=re.search(r'^### '+re.escape(id)+r'\n(.*?)(?=^### |\Z)',raw,re.S|re.M)
            canonical[id]={'id':id,'kind':m[1],'path':str(path.relative_to(ROOT)),'line':raw[:m.start()].count('\n')+1,'body':body,'body_sha256':hashlib.sha256(body.encode()).hexdigest(),'metadata':meta[1].strip() if meta else '', 'iter3_groups':[]}
    bindings=[];source_files={}
    for g in GROUPS:
        assert g['ontology'] in canonical,g['ontology'];canonical[g['ontology']]['iter3_groups'].append(g['id'])
        model=FORMAL/g['model'];raw=model.read_text()
        for symbol in g['symbols']+g['proofs']:assert re.search(r'\bfn '+re.escape(symbol)+r'\b',raw),(g['id'],symbol)
        g['formal_sha256']=sha(model)
        g['native_matches']={k:json.loads((HERE/'native/receipt.json').read_text())['observations'][k] for k in g['native_keys']}
        for member in g['members']:
            assert member in inventory,(g['id'],member)
            r=inventory[member];path='src/cls/IPM/'+member.split('::')[0]
            if path not in source_files:source_files[path]=git('show',PIN+':'+path)
            old_span=r['source_slice'].rsplit(':',1)[1];start,end=map(int,old_span.split('-'))
            lines=source_files[path].splitlines();snippet='\n'.join(lines[start-1:end])+'\n'
            row={'id':g['id']+'-'+str(len(bindings)+1),'group':g['id'],'member':member,'source':path,'start':start,'end':end,'source_sha256':hashlib.sha256(snippet.encode()).hexdigest(),'owner':g['ontology'],'formal':str(model.relative_to(ROOT)),'symbols':g['symbols'],'proofs':g['proofs'],'scope':g['remaining_scope'],'evidence':['source-inspected','Verus-abstract-contract']+(['native-observation'] if g['native_keys'] else []),'implementation_proof':False,'whole_member_verified':False}
            bindings.append(row)
            r.setdefault('iter3_bindings',[]).append(row['id']);r['iter3_scope']='decision-kernel-and-source-boundary; no whole-member proof'
    reviewed={b['member'] for b in bindings}
    remaining=[m for m,r in inventory.items() if r.get('review_status')=='still-unclassified' and m not in reviewed]
    result={'product_pin':PIN,'counting_rule':'Original ClassMethod|Method|Query|Trigger denominator unchanged, every original member retained. A source link is not representation of every branch.','denominator':1216,'canonical_blocks':len(canonical),'groups':GROUPS,'bindings':bindings,'source_traced_members':len(reviewed),'previously_unclassified_now_scoped':sum(inventory[m].get('review_status')=='still-unclassified' for m in reviewed),'still_unclassified_in_inherited_census':len(remaining),'implementation_proofs':0,'proof_receipt':'.g5/uplift/consolidated/iter3/proofs/models.json','native_receipt':'.g5/uplift/consolidated/iter3/native/receipt.json','native_bridge':'.g5/uplift/consolidated/iter3/proofs/native-bridge.json'}
    (HERE/'INDEX.json').write_text(json.dumps(result,indent=2)+'\n')
    (HERE/'canonical-index.json').write_text(json.dumps(list(canonical.values()),indent=2)+'\n')
    (HERE/'inventory.json').write_text(json.dumps({'pin':PIN,'denominator':1216,'members':list(inventory.values()),'remaining_unclassified':remaining},indent=2)+'\n')
    chunks=[]
    for m in sorted(reviewed):
        r=inventory[m];path='src/cls/IPM/'+m.split('::')[0];a,b=map(int,r['source_slice'].rsplit(':',1)[1].split('-'))
        chunks.append('\n'+m+' '+r['source_slice']+'\n'+'\n'.join(source_files[path].splitlines()[a-1:b])+'\n')
    (HERE/'source-slices.txt').write_text(''.join(chunks))
    print(json.dumps({k:result[k] for k in ['denominator','canonical_blocks','source_traced_members','previously_unclassified_now_scoped','still_unclassified_in_inherited_census','implementation_proofs']}))
if __name__=='__main__':main()
